/**
 * activity_vectors.test.ts — the shared activity-target vectors
 * (tests/fixtures/activity_targets.json, generated by
 * tests/fixtures/make_activity_targets.py) run against the TypeScript
 * builder, exactly like Hermes's tests/tools/test_activity_target_vectors.py:
 * every virtual absolute path (`cwd`, `env.HOME`, `env.USERPROFILE`,
 * `args.path`, `fs`) is mapped into a fresh temp directory that models `/`,
 * the `fs` entries are created (files, directories, symlinks), and the
 * process identity comes from `system_user` / `system_home`, never from the
 * machine. Nothing outside the temp directories is written.
 */

import { mkdirSync, mkdtempSync, realpathSync, rmSync, symlinkSync, lstatSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import nodePath from 'node:path';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { afterEach, describe, expect, it } from 'vitest';

import {
  ACTIVITY_LABEL_CHARS,
  activityQuery,
  activitySeams,
  buildActivity,
  renderActivityBlock,
  resetActivityCaches,
} from '../src/index.js';
import type { Activity, ActivitySpec } from '../src/index.js';

const VECTORS = fileURLToPath(new URL('../../../tests/fixtures/activity_targets.json', import.meta.url));

interface Vector {
  name: string;
  tool: string;
  args: Record<string, unknown>;
  cwd: string;
  env: Record<string, string>;
  fs: Array<string | { symlink: string; to: string }>;
  expected_query: string | null;
  expected_line: string | null;
  key_distinct_from?: string;
  system_user?: string;
  system_home?: string;
}

const load = (): Vector[] => JSON.parse(readFileSync(VECTORS, 'utf8')) as Vector[];

/** Hermes tool → neutral spec (the vectors use Hermes tool names). */
function spec(tool: string, args: Record<string, unknown>): ActivitySpec | null {
  switch (tool) {
    case 'read_file':
      return { verb: 'read', path: args.path };
    case 'write_file':
      return { verb: 'write', path: args.path };
    case 'patch':
      return { verb: 'edit', path: args.path };
    case 'search_files':
      return { verb: 'search', pattern: args.pattern, path: args.path };
    case 'terminal':
      return { verb: 'run', command: args.command };
    default:
      return null;
  }
}

const savedSeams = { ...activitySeams };

/** One case's fake filesystem under a directory that models `/`. */
class World {
  readonly tmp: string;
  symlinksOk = true;

  constructor(c: Vector, tmp: string) {
    mkdirSync(tmp, { recursive: true });
    this.tmp = realpathSync(tmp);
    for (const entry of c.fs) this.create(entry);
  }

  map(value: unknown): unknown {
    if (typeof value === 'string' && value.startsWith('/')) {
      return nodePath.join(this.tmp, ...value.split('/').filter((p) => p !== ''));
    }
    return value;
  }

  create(entry: string | { symlink: string; to: string }): void {
    if (typeof entry === 'object') {
      const target = this.map(entry.to) as string;
      mkdirSync(target, { recursive: true });
      const link = this.map(entry.symlink) as string;
      mkdirSync(nodePath.dirname(link), { recursive: true });
      let exists = true;
      try {
        lstatSync(link);
      } catch {
        exists = false;
      }
      if (!exists) {
        try {
          symlinkSync(target, link, 'dir');
        } catch {
          this.symlinksOk = false;
        }
      }
    } else if (entry.endsWith('/')) {
      mkdirSync(this.map(entry) as string, { recursive: true });
    } else {
      const p = this.map(entry) as string;
      mkdirSync(nodePath.dirname(p), { recursive: true });
      writeFileSync(p, '');
    }
  }

  build(c: Vector): Activity | null {
    const cwd = this.map(c.cwd) as string;
    if (cwd.startsWith(this.tmp)) mkdirSync(cwd, { recursive: true });
    const env: Record<string, string> = {};
    for (const [k, v] of Object.entries(c.env)) env[k] = (k === 'HOME' || k === 'USERPROFILE' ? this.map(v) : v) as string;
    const args = { ...c.args };
    if (typeof args.path === 'string') args.path = this.map(args.path);
    const tmp = this.tmp;
    const home = c.system_home ? [this.map(c.system_home) as string] : [];
    const identity: [string[], string[], string[]] = [c.system_user ? [c.system_user] : [], home, home];
    activitySeams.fsRoot = (d: string) => d === tmp || !d.startsWith(tmp + nodePath.sep);
    activitySeams.systemIdentity = () => identity;
    resetActivityCaches();
    try {
      const s = spec(c.tool, args);
      return s === null ? null : buildActivity(s, cwd, env);
    } finally {
      Object.assign(activitySeams, savedSeams);
      resetActivityCaches();
    }
  }

  close(): void {
    rmSync(this.tmp, { recursive: true, force: true });
  }
}

/**
 * Build each case in its own world, one after the other, at the SAME path
 * under one temp dir (Hermes `build`): no cross-talk between `fs` lists, and
 * keys (digests of full paths) stay comparable.
 */
function buildIn(...cases: Vector[]): { tmp: string; built: Array<Activity | null> | null } {
  const parent = mkdtempSync(nodePath.join(tmpdir(), 'ct-activity-'));
  const built: Array<Activity | null> = [];
  let tmp = '';
  try {
    for (const c of cases) {
      const world = new World(c, nodePath.join(parent, 'w'));
      tmp = world.tmp;
      if (!world.symlinksOk) return { tmp, built: null };
      built.push(world.build(c));
      world.close();
    }
    return { tmp, built };
  } finally {
    rmSync(parent, { recursive: true, force: true });
  }
}

afterEach(() => {
  Object.assign(activitySeams, savedSeams);
  resetActivityCaches();
});

describe('shared activity-target vectors (Hermes parity, privacy amendments 4 and 5)', () => {
  it('the vector file has the documented shape', () => {
    const cases = load();
    expect(cases.length).toBeGreaterThanOrEqual(290);
    const names = cases.map((c) => c.name);
    expect(new Set(names).size).toBe(names.length);
    const fields = ['name', 'tool', 'args', 'cwd', 'env', 'fs', 'expected_query', 'expected_line'];
    for (const c of cases) {
      const extra = Object.keys(c).filter((k) => !fields.includes(k));
      expect(extra.every((k) => ['key_distinct_from', 'system_user', 'system_home'].includes(k)), c.name).toBe(true);
      expect(c.expected_query === null, c.name).toBe(c.expected_line === null);
    }
  });

  it('every vector: query and label', () => {
    let skipped = 0;
    for (const c of load()) {
      const { tmp, built } = buildIn(c);
      if (built === null) {
        skipped++;
        continue;
      }
      const a = built[0];
      if (c.expected_query === null) {
        expect(a === null || activityQuery(a) === '', `${c.name}: expected no query, got ${a?.line}`).toBe(true);
        continue;
      }
      expect(a, c.name).not.toBeNull();
      expect(activityQuery(a!), c.name).toBe(c.expected_query);
      expect(a!.line, c.name).toBe(c.expected_line);
      expect(JSON.stringify(a), c.name).not.toContain(tmp);
      const block = renderActivityBlock({ id: 'f1', title: 'T', text: 'x', provenance: 'p' }, [], a!);
      let label = c.expected_line!;
      if (label.length > ACTIVITY_LABEL_CHARS) label = `${label.slice(0, ACTIVITY_LABEL_CHARS - 1)}…`;
      expect(block, c.name).toContain(`_for: ${label}_`);
    }
    expect(skipped).toBe(0);
  });

  it('key_distinct_from: equal queries, distinct local keys (one shared world)', () => {
    const cases = new Map(load().map((c) => [c.name, c]));
    let checked = 0;
    for (const c of cases.values()) {
      if (!c.key_distinct_from) continue;
      const { built } = buildIn(c, cases.get(c.key_distinct_from)!, c);
      expect(built, c.name).not.toBeNull();
      const [a, b, again] = built!;
      expect(a!.key, `${c.name}: keys are comparable across worlds`).toBe(again!.key);
      expect(activityQuery(a!), c.name).toBe(activityQuery(b!));
      expect(a!.key, c.name).not.toBe(b!.key);
      checked++;
    }
    expect(checked).toBeGreaterThan(0);
  });
});
